@IsTest private class E51C0408Test{
@TestSetup static void captureSeed(){Map<String,Object> r=new Map<String,Object>();try{
Integer p=Limits.getPublishImmediateDml(),d=Limits.getDmlStatements(),n=Limits.getDmlRows();r.put('publishReturned',false);r.put('resultNull',null);try{Database.SaveResult single=EventBus.publish((C51A62Signal__e)null);r.put('resultNull',single==null);List<Database.SaveResult> saved=single==null?null:new List<Database.SaveResult>{single};r.put('publishReturned',true);List<Object> results=new List<Object>();if(saved!=null){for(Database.SaveResult result:saved){if(result==null){results.add(null);continue;}List<Object> errors=new List<Object>();for(Database.Error err:result.getErrors()){errors.add(new Map<String,Object>{'status'=>String.valueOf(err.getStatusCode()),'message'=>err.getMessage(),'fields'=>err.getFields()});}results.add(new Map<String,Object>{'success'=>result.isSuccess(),'id'=>result.getId(),'errors'=>errors});}}r.put('results',results);}catch(Exception fault){r.put('exceptionType',fault.getTypeName());r.put('exceptionMessage',fault.getMessage());r.put('stack',fault.getStackTraceString());}r.put('publishImmediateDelta',Limits.getPublishImmediateDml()-p);r.put('dmlStatementsDelta',Limits.getDmlStatements()-d);r.put('dmlRowsDelta',Limits.getDmlRows()-n);r.put('completed',true);
