C51A62Signal__e value=new C51A62Signal__e();Integer p=Limits.getPublishImmediateDml(),d=Limits.getDmlStatements(),n=Limits.getDmlRows();r.put('publishReturned',false);r.put('resultNull',null);try{List<Database.SaveResult> saved=EventBus.publish(new List<C51A62Signal__e>{value,value});r.put('resultNull',saved==null);r.put('publishReturned',true);List<Object> results=new List<Object>();if(saved!=null){for(Database.SaveResult result:saved){if(result==null){results.add(null);continue;}List<Object> errors=new List<Object>();for(Database.Error err:result.getErrors()){errors.add(new Map<String,Object>{'status'=>String.valueOf(err.getStatusCode()),'message'=>err.getMessage(),'fields'=>err.getFields()});}results.add(new Map<String,Object>{'success'=>result.isSuccess(),'id'=>result.getId(),'errors'=>errors});}}r.put('results',results);}catch(Exception fault){r.put('exceptionType',fault.getTypeName());r.put('exceptionMessage',fault.getMessage());r.put('stack',fault.getStackTraceString());}r.put('publishImmediateDelta',Limits.getPublishImmediateDml()-p);r.put('dmlStatementsDelta',Limits.getDmlStatements()-d);r.put('dmlRowsDelta',Limits.getDmlRows()-n);r.put('completed',true);
