@IsTest private class E51C0407Test{
@TestSetup static void captureSeed(){Map<String,Object> r=new Map<String,Object>();try{
Integer p=Limits.getPublishImmediateDml(),d=Limits.getDmlStatements(),n=Limits.getDmlRows();r.put('publishReturned',false);r.put('resultNull',null);try{List<Database.SaveResult> saved=EventBus.publish(new List<C51A67Signal__e>{new C51A67Signal__e(PulseCode__c='a'),new C51A67Signal__e(PulseCode__c='b')});r.put('resultNull',saved==null);r.put('publishReturned',true);List<Object> results=new List<Object>();if(saved!=null){for(Database.SaveResult result:saved){if(result==null){results.add(null);continue;}List<Object> errors=new List<Object>();for(Database.Error err:result.getErrors()){errors.add(new Map<String,Object>{'status'=>String.valueOf(err.getStatusCode()),'message'=>err.getMessage(),'fields'=>err.getFields()});}results.add(new Map<String,Object>{'success'=>result.isSuccess(),'id'=>result.getId(),'errors'=>errors});}}r.put('results',results);}catch(Exception fault){r.put('exceptionType',fault.getTypeName());r.put('exceptionMessage',fault.getMessage());r.put('stack',fault.getStackTraceString());}r.put('publishImmediateDelta',Limits.getPublishImmediateDml()-p);r.put('dmlStatementsDelta',Limits.getDmlStatements()-d);r.put('dmlRowsDelta',Limits.getDmlRows()-n);r.put('completed',true);
}catch(Exception captureException){r.put('exceptionType',captureException.getTypeName());r.put('exceptionMessage',captureException.getMessage());r.put('stack',captureException.getStackTraceString());}String capturePayload=JSON.serialize(r);if(capturePayload.length()>32000){capturePayload=JSON.serialize(new Map<String,Object>{'captureTransportError'=>'test-setup-payload-overflow','rawCharacters'=>capturePayload.length()});}insert new Account(Name='E51_PAYLOAD',Description=capturePayload);}
